import React, { createContext, useState, useContext, useEffect } from 'react';

const OrderContext = createContext();

export const useOrders = () => useContext(OrderContext);

export const OrderProvider = ({ children }) => {
  // Initialize state from localStorage
  const [orders, setOrders] = useState(() => {
    try {
      const localData = localStorage.getItem('gardenia-orders');
      return localData ? JSON.parse(localData) : [];
    } catch (error) {
      console.error("Could not parse orders from localStorage", error);
      return [];
    }
  });

  // Persist state to localStorage whenever it changes
  useEffect(() => {
    try {
      localStorage.setItem('gardenia-orders', JSON.stringify(orders));
    } catch (error) {
      console.error("Could not save orders to localStorage", error);
    }
  }, [orders]);

  const addOrder = (orderData) => {
    const newOrder = {
      ...orderData,
      id: `ORD-${Date.now()}`,
      date: new Date(),
      status: 'Processing',
    };
    setOrders(prevOrders => [newOrder, ...prevOrders]);
  };

  const value = {
    orders,
    addOrder,
  };

  return <OrderContext.Provider value={value}>{children}</OrderContext.Provider>;
};
